  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: em novembro e dezembro, 1/11 do ano corrente; de janeiro a outubro, 1/11 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08 e de 1/10 para 1/11 em 2026-11-11 (base limpa, coleta do zero).
  // Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo" e o CICLO_MES de js/formato.js.
  cicloInicio: { mes: 11, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
// acao.idUnidade é obrigatório: o mesmo IdPaciente pode existir em duas unidades.
const sqlRegistrarAcao = (acao) => {
  const unidade = sqlN(acao.idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlRegistrarAcao: idUnidade não informado.');
  }
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${unidade} AS IdUnidade, ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdUnidade = origem.IdUnidade AND destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdUnidade, IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdUnidade, IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra } da unidade. Blocos de 500 (VALUES aceita até 1000 linhas).
// Os ids das listas do CNN são de cada clínica: a chave é (IdUnidade, Tipo, Id).
const sqlCadastros = (linhas, idUnidade) => {
  const unidade = sqlN(idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlCadastros: idUnidade não informado.');
  }
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.IdUnidade = ${unidade} AND destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (IdUnidade, Tipo, Id, Nome, Extra) VALUES (${unidade}, origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// ===== Unidade da execução (fonte única: workflows/code/_unidade.js) =====
// Cada unidade (clínica do CNN) tem um IdUnidade (chave em todas as tabelas) e um código (dbo.CtlCnnUnidade).
// O CID do CNN de cada unidade fica na variável do n8n CNN_CID_<código> (ex.: CNN_CID_ZARNS_SALVADOR), na tela
// Variables ($vars) ou no ambiente do servidor ($env), nunca no fluxo: os headers "clinicaNasNuvens-cid" leem por ela.
const CODIGO_UNIDADE = /^[A-Z0-9_]{1,40}$/;

// { idUnidade, codigoUnidade } de quem chamou (a Vercel no webhook, ou o fluxo principal no subfluxo do bloqueio).
const lerUnidade = (origem) => {
  const idUnidade = Number(origem?.idUnidade);
  const codigoUnidade = String(origem?.codigoUnidade ?? '').trim();
  if (!Number.isSafeInteger(idUnidade) || idUnidade <= 0 || idUnidade > 32767 || !CODIGO_UNIDADE.test(codigoUnidade)) {
    return null;
  }
  return { idUnidade, codigoUnidade };
};

// Unidade desta execução: nó "Unidade" (subfluxo do bloqueio) ou "Validar" (workflow Ações).
const unidadeAtual = () => {
  for (const nome of ['Unidade', 'Validar']) {
    try {
      const unidade = lerUnidade($(nome).first().json);
      if (unidade) {
        return unidade;
      }
    } catch (erro) {
      // o nó não existe (ou não rodou) neste workflow
    }
  }
  throw new Error('Unidade não informada nesta execução (idUnidade e codigoUnidade).');
};

// CID da unidade: Variables do n8n ($vars, tela Variables) e, se não tiver, variável de ambiente do servidor ($env).
// Vazio: a chamada ao CNN não pode seguir.
const cidDaUnidade = (codigoUnidade) => {
  const nome = `CNN_CID_${codigoUnidade}`;
  for (const ler of [() => $vars[nome], () => $env[nome]]) {
    try {
      const valor = String(ler() ?? '').trim();
      if (valor) {
        return valor;
      }
    } catch (erro) {
      // $vars indisponível, ou N8N_BLOCK_ENV_ACCESS_IN_NODE=true bloqueando o $env
    }
  }
  return '';
};

const semCidMensagem = (codigoUnidade) =>
  `CID da unidade ${codigoUnidade} não configurado no n8n (variável CNN_CID_${codigoUnidade} em Variables).`;
// ===== fim da unidade =====

// Nó "preparar insert SQL" (bloqueio às 01:00 e botão Bloquear do painel).
// Monta uma query só para o nó "gravar faltas" (o nó Microsoft SQL roda só a query do 1º item), numa transação:
//   1. cadastros (nomes de tipo de consulta, profissional, rótulo, local, especialidade): MERGE em CtlCnnCadastro;
//   2. todas as faltas lidas vão para a tabela temporária #faltas (INSERT de até 1000 linhas por vez);
//   3. falta já gravada: UPDATE dos dados da agenda (tipo de consulta, rótulo, profissional, local, horário),
//      que podem mudar no CNN; dados do paciente só completam o que estiver vazio;
//   4. falta nova: INSERT (NumeroFalta provisório 0, acertado no passo 6);
//   5. procedimentos das faltas lidas: apaga e grava de novo (CtlCnnFaltaProcedimento);
//   6. renumera NumeroFalta por data no ciclo, para os pacientes lidos.
// Profissional: a agenda traz idPessoaExecutor, que é o "idpessoa" da lista /executor-agenda/lista
// (não o "id" do executor; por isso o GET /executor-agenda/{id} antigo nunca achava ninguém).
// Tudo na unidade desta execução (subfluxo do bloqueio ou Validar do workflow Ações).
const inicioPeriodo = inicioCiclo();
const { idUnidade } = unidadeAtual();
const faltas = $('separar faltas').all().filter((item) => !item.json.semFaltas).map((item) => item.json ?? {});

if (!faltas.length) {
  return [];
}

// Pacientes por id (o GET roda uma vez por paciente, no nó "pacientes únicos").
const pacientes = new Map();
for (const item of itensDoNo('GET paciente por id')) {
  const paciente = item.json ?? {};
  const id = Number(paciente.id);
  if (Number.isFinite(id) && !paciente.error && !paciente.message) {
    pacientes.set(id, paciente);
  }
}

// Listas de cadastro. Nó que não existe neste workflow (Ações só lê executores) ou que falhou: lista vazia.
const executores = listaDaApi(itensDoNo('GET executores'));
const executorPorPessoa = new Map();
for (const executor of executores) {
  const idPessoa = Number(executor.idpessoa);
  if (Number.isFinite(idPessoa)) {
    executorPorPessoa.set(idPessoa, executor);
  }
}

const cadastros = [
  ...listaDaApi(itensDoNo('GET tipos de consulta')).map((t) => ({ tipo: 'TIPO_CONSULTA', id: t.id, nome: t.nome, extra: t.reconsulta === true ? 'RECONSULTA' : null })),
  ...executores.map((e) => ({ tipo: 'EXECUTOR', id: e.idpessoa, nome: e.nome, extra: e.tipoExecutor || null })),
  ...listaDaApi(itensDoNo('GET rótulos')).map((r) => ({ tipo: 'ROTULO', id: r.id, nome: r.nome, extra: r.corRotulo || null })),
  ...listaDaApi(itensDoNo('GET locais')).map((l) => ({ tipo: 'LOCAL_AGENDA', id: l.id, nome: l.nome, extra: null })),
  ...listaDaApi(itensDoNo('GET especialidades')).map((e) => ({ tipo: 'ESPECIALIDADE', id: e.id, nome: e.nome, extra: null })),
];

// Procedimentos de uma falta, sem repetir o mesmo tipo (soma a quantidade).
const procedimentosDe = (falta) => {
  const porTipo = new Map();
  for (const proc of Array.isArray(falta.procedimentos) ? falta.procedimentos : []) {
    const idTipo = Number(proc?.idTipoProcedimento);
    if (!Number.isFinite(idTipo)) {
      continue;
    }
    const atual = porTipo.get(idTipo);
    const quantidade = Number(proc.quantidade) || 1;
    if (atual) {
      atual.quantidade += quantidade;
    } else {
      porTipo.set(idTipo, { idTipo, nome: proc.nome, idEspecialidade: proc.idEspecialidade, quantidade });
    }
  }
  return [...porTipo.values()];
};

// A mesma falta pode aparecer duas vezes se a agenda mudar entre uma página e outra: fica a última.
const porAgenda = new Map();
for (const falta of faltas) {
  if (sqlN(falta.id) !== 'NULL') {
    porAgenda.set(Number(falta.id), falta);
  }
}

const linhaFalta = (falta) => {
  const paciente = pacientes.get(Number(falta.idPaciente)) || null;
  const contato = paciente?.contato ?? {};
  const executor = executorPorPessoa.get(Number(falta.idPessoaExecutor)) || null;

  return `(${[
    sqlN(falta.id),
    sqlN(falta.idPaciente),
    sqlS(paciente ? paciente.nome : null, 200),
    sqlS(paciente ? paciente.cpfcnpj : null, 20),
    sqlS(contato.email || falta.emailPaciente, 200),
    sqlS(contato.telefoneCelular || falta.telefoneCelularPaciente, 30),
    sqlDate(falta.dataFalta || falta.data),
    sqlTime(falta.horaInicio),
    sqlTime(falta.horaFim),
    sqlS(falta.status, 50),
    sqlN(falta.idPessoaExecutor),
    sqlN(executor ? executor.id : null),
    sqlS(executor ? executor.nome : null, 200),
    sqlS(executor ? executor.tipoExecutor : null, 50),
    sqlN(falta.idLocalAgenda),
    sqlN(falta.idTipoConsulta),
    sqlN(falta.idRotulo),
    sqlS(falta.observacoes, 500),
  ].join(', ')})`;
};

const emBlocos = (linhas, tamanho, montar) => {
  const blocos = [];
  for (let i = 0; i < linhas.length; i += tamanho) {
    blocos.push(montar(linhas.slice(i, i + tamanho)));
  }
  return blocos.join('\n');
};

const linhasFaltas = [...porAgenda.values()].map(linhaFalta);
const linhasProcedimentos = [...porAgenda.values()].flatMap((falta) =>
  procedimentosDe(falta).map((proc) =>
    `(${sqlN(idUnidade)}, ${sqlN(falta.id)}, ${sqlN(proc.idTipo)}, ${sqlS(proc.nome, 200)}, ${sqlN(proc.idEspecialidade)}, ${sqlN(proc.quantidade)})`
  )
);

const idsPacientes = [...new Set(faltas.map((falta) => Number(falta.idPaciente)).filter((id) => Number.isFinite(id)))];

const query = `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @unidade SMALLINT = ${sqlN(idUnidade)};
${sqlCadastros(cadastros, idUnidade)}

IF OBJECT_ID(N'tempdb..#faltas') IS NOT NULL
    DROP TABLE #faltas;

CREATE TABLE #faltas (
    IdAgenda BIGINT NOT NULL PRIMARY KEY,
    IdPaciente BIGINT NOT NULL,
    NomePaciente NVARCHAR(200) NULL,
    CpfCnpj NVARCHAR(20) NULL,
    EmailPaciente NVARCHAR(200) NULL,
    TelefonePaciente NVARCHAR(30) NULL,
    DataFalta DATE NOT NULL,
    HoraInicio TIME(0) NULL,
    HoraFim TIME(0) NULL,
    StatusAgenda NVARCHAR(50) NOT NULL,
    IdPessoaExecutor BIGINT NULL,
    IdExecutorAgenda BIGINT NULL,
    NomeExecutor NVARCHAR(200) NULL,
    TipoExecutor NVARCHAR(50) NULL,
    IdLocalAgenda BIGINT NULL,
    IdTipoConsulta BIGINT NULL,
    IdRotulo BIGINT NULL,
    Observacoes NVARCHAR(500) NULL
);

${emBlocos(linhasFaltas, 1000, (bloco) => `INSERT INTO #faltas VALUES
    ${bloco.join(',\n    ')};`)}

UPDATE destino
SET
    HoraInicio = origem.HoraInicio,
    HoraFim = origem.HoraFim,
    IdPessoaExecutor = origem.IdPessoaExecutor,
    IdExecutorAgenda = COALESCE(origem.IdExecutorAgenda, destino.IdExecutorAgenda),
    NomeExecutor = COALESCE(origem.NomeExecutor, destino.NomeExecutor),
    TipoExecutor = COALESCE(origem.TipoExecutor, destino.TipoExecutor),
    IdLocalAgenda = origem.IdLocalAgenda,
    IdTipoConsulta = origem.IdTipoConsulta,
    IdRotulo = origem.IdRotulo,
    Observacoes = origem.Observacoes,
    NomePaciente = COALESCE(destino.NomePaciente, origem.NomePaciente),
    CpfCnpj = COALESCE(destino.CpfCnpj, origem.CpfCnpj),
    EmailPaciente = COALESCE(destino.EmailPaciente, origem.EmailPaciente),
    TelefonePaciente = COALESCE(destino.TelefonePaciente, origem.TelefonePaciente)
FROM dbo.CtlCnnFaltaPaciente AS destino
INNER JOIN #faltas AS origem
    ON origem.IdAgenda = destino.IdAgenda
WHERE destino.IdUnidade = @unidade;

INSERT INTO dbo.CtlCnnFaltaPaciente (
    IdUnidade, IdAgenda, IdPaciente, NomePaciente, CpfCnpj, EmailPaciente, TelefonePaciente,
    DataFalta, HoraInicio, HoraFim, StatusAgenda,
    IdPessoaExecutor, IdExecutorAgenda, NomeExecutor, TipoExecutor,
    IdLocalAgenda, IdTipoConsulta, IdRotulo, Observacoes, NumeroFalta
)
SELECT
    @unidade, origem.IdAgenda, origem.IdPaciente, origem.NomePaciente, origem.CpfCnpj, origem.EmailPaciente, origem.TelefonePaciente,
    origem.DataFalta, origem.HoraInicio, origem.HoraFim, origem.StatusAgenda,
    origem.IdPessoaExecutor, origem.IdExecutorAgenda, origem.NomeExecutor, origem.TipoExecutor,
    origem.IdLocalAgenda, origem.IdTipoConsulta, origem.IdRotulo, origem.Observacoes, 0
FROM #faltas AS origem
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.CtlCnnFaltaPaciente f WHERE f.IdUnidade = @unidade AND f.IdAgenda = origem.IdAgenda
);

DECLARE @novas INT = @@ROWCOUNT;

DELETE p
FROM dbo.CtlCnnFaltaProcedimento AS p
INNER JOIN #faltas AS origem
    ON origem.IdAgenda = p.IdAgenda
WHERE p.IdUnidade = @unidade;

${emBlocos(linhasProcedimentos, 1000, (bloco) => `INSERT INTO dbo.CtlCnnFaltaProcedimento (IdUnidade, IdAgenda, IdTipoProcedimento, NomeProcedimento, IdEspecialidade, Quantidade)
VALUES
    ${bloco.join(',\n    ')};`)}

-- Reordena NumeroFalta por data dentro do ciclo (uma falta antiga pode chegar depois de uma nova; as novas entram com 0).
;WITH Numeracao AS (
    SELECT
        Id,
        ROW_NUMBER() OVER (
            PARTITION BY IdPaciente
            ORDER BY DataFalta, IdAgenda
        ) AS NumeroCalculado
    FROM dbo.CtlCnnFaltaPaciente
    WHERE IdUnidade = @unidade
      AND IdPaciente IN (SELECT DISTINCT IdPaciente FROM #faltas)
      AND DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
)
UPDATE destino
SET NumeroFalta = origem.NumeroCalculado
FROM dbo.CtlCnnFaltaPaciente AS destino
INNER JOIN Numeracao AS origem
    ON origem.Id = destino.Id
WHERE destino.NumeroFalta <> origem.NumeroCalculado;

DROP TABLE #faltas;

COMMIT TRANSACTION;

SELECT CAST(${porAgenda.size} AS int) AS faltasLidas, @novas AS faltasNovas, CAST(${cadastros.length} AS int) AS cadastrosLidos;`;

return [{
  json: {
    query,
    idUnidade,
    quantidadeFaltas: porAgenda.size,
    quantidadeCadastros: cadastros.length,
    dataInicioPeriodo: inicioPeriodo,
    idsPacientes,
    listaIds: idsPacientes.join(', ')
  }
}];

parameters.query:
USE INTEGRACAO;

-- Sem faltas novas neste ciclo. Nada a inserir.
SELECT CAST(0 AS int) AS quantidadeFaltas;

parameters.jsCode:
// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: em novembro e dezembro, 1/11 do ano corrente; de janeiro a outubro, 1/11 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08 e de 1/10 para 1/11 em 2026-11-11 (base limpa, coleta do zero).
  // Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo" e o CICLO_MES de js/formato.js.
  cicloInicio: { mes: 11, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
// acao.idUnidade é obrigatório: o mesmo IdPaciente pode existir em duas unidades.
const sqlRegistrarAcao = (acao) => {
  const unidade = sqlN(acao.idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlRegistrarAcao: idUnidade não informado.');
  }
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${unidade} AS IdUnidade, ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdUnidade = origem.IdUnidade AND destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdUnidade, IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdUnidade, IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra } da unidade. Blocos de 500 (VALUES aceita até 1000 linhas).
// Os ids das listas do CNN são de cada clínica: a chave é (IdUnidade, Tipo, Id).
const sqlCadastros = (linhas, idUnidade) => {
  const unidade = sqlN(idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlCadastros: idUnidade não informado.');
  }
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.IdUnidade = ${unidade} AND destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (IdUnidade, Tipo, Id, Nome, Extra) VALUES (${unidade}, origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// ===== Unidade da execução (fonte única: workflows/code/_unidade.js) =====
// Cada unidade (clínica do CNN) tem um IdUnidade (chave em todas as tabelas) e um código (dbo.CtlCnnUnidade).
// O CID do CNN de cada unidade fica na variável do n8n CNN_CID_<código> (ex.: CNN_CID_ZARNS_SALVADOR), na tela
// Variables ($vars) ou no ambiente do servidor ($env), nunca no fluxo: os headers "clinicaNasNuvens-cid" leem por ela.
const CODIGO_UNIDADE = /^[A-Z0-9_]{1,40}$/;

// { idUnidade, codigoUnidade } de quem chamou (a Vercel no webhook, ou o fluxo principal no subfluxo do bloqueio).
const lerUnidade = (origem) => {
  const idUnidade = Number(origem?.idUnidade);
  const codigoUnidade = String(origem?.codigoUnidade ?? '').trim();
  if (!Number.isSafeInteger(idUnidade) || idUnidade <= 0 || idUnidade > 32767 || !CODIGO_UNIDADE.test(codigoUnidade)) {
    return null;
  }
  return { idUnidade, codigoUnidade };
};

// Unidade desta execução: nó "Unidade" (subfluxo do bloqueio) ou "Validar" (workflow Ações).
const unidadeAtual = () => {
  for (const nome of ['Unidade', 'Validar']) {
    try {
      const unidade = lerUnidade($(nome).first().json);
      if (unidade) {
        return unidade;
      }
    } catch (erro) {
      // o nó não existe (ou não rodou) neste workflow
    }
  }
  throw new Error('Unidade não informada nesta execução (idUnidade e codigoUnidade).');
};

// CID da unidade: Variables do n8n ($vars, tela Variables) e, se não tiver, variável de ambiente do servidor ($env).
// Vazio: a chamada ao CNN não pode seguir.
const cidDaUnidade = (codigoUnidade) => {
  const nome = `CNN_CID_${codigoUnidade}`;
  for (const ler of [() => $vars[nome], () => $env[nome]]) {
    try {
      const valor = String(ler() ?? '').trim();
      if (valor) {
        return valor;
      }
    } catch (erro) {
      // $vars indisponível, ou N8N_BLOCK_ENV_ACCESS_IN_NODE=true bloqueando o $env
    }
  }
  return '';
};

const semCidMensagem = (codigoUnidade) =>
  `CID da unidade ${codigoUnidade} não configurado no n8n (variável CNN_CID_${codigoUnidade} em Variables).`;
// ===== fim da unidade =====

// Nó "ids da consulta" (bloqueio às 01:00). Monta a consulta do nó "consultar bloqueios":
// a falta vigente (MAX(NumeroFalta) no ciclo) de cada paciente do lote.
// Fica de fora quem foi liberado pelo painel com essa mesma falta vigente: o bloqueio não desfaz a liberação manual.
// Uma falta nova muda a vigente, e o paciente volta a ser bloqueado normalmente.
const fonteInsert = $('preparar insert SQL');

if (!fonteInsert.isExecuted) {
  return [];
}

const ids = fonteInsert.first()?.json?.idsPacientes ?? [];
const listaIds = Array.isArray(ids)
  ? ids.map((id) => Number(id)).filter((id) => Number.isFinite(id)).join(', ')
  : '';

if (!listaIds) {
  return [];
}

const inicioPeriodo = fonteInsert.first()?.json?.dataInicioPeriodo || inicioCiclo();
const { idUnidade } = unidadeAtual();

const query = `USE INTEGRACAO;

DECLARE @unidade SMALLINT = ${sqlN(idUnidade)};

SELECT
    f.IdAgenda,
    f.IdPaciente,
    f.NomePaciente,
    f.DataFalta,
    f.NumeroFalta,
    ctl.Situacao AS SituacaoControle,
    ctl.IdAgendaReferencia
FROM dbo.CtlCnnFaltaPaciente f
LEFT JOIN dbo.CtlCnnControlePaciente ctl
    ON ctl.IdUnidade = f.IdUnidade
   AND ctl.IdPaciente = f.IdPaciente
INNER JOIN (
    SELECT
        IdPaciente,
        MAX(NumeroFalta) AS NumeroFalta
    FROM dbo.CtlCnnFaltaPaciente
    WHERE IdUnidade = @unidade
      AND IdPaciente IN (${listaIds})
      AND DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
    GROUP BY IdPaciente
) atual
    ON atual.IdPaciente = f.IdPaciente
   AND atual.NumeroFalta = f.NumeroFalta
WHERE f.IdUnidade = @unidade
  AND f.DataFalta >= CONVERT(date, '${inicioPeriodo}', 23)
  AND NOT EXISTS (
        SELECT 1
        FROM dbo.CtlCnnControlePaciente c
        WHERE c.IdUnidade = f.IdUnidade
          AND c.IdPaciente = f.IdPaciente
          AND c.Situacao = N'LIBERADO'
          AND c.IdAgendaReferencia = f.IdAgenda
  );`;

return [{
  json: {
    query,
    idUnidade,
    listaIds,
    idsPacientes: ids,
    dataInicioPeriodo: inicioPeriodo
  }
}];

// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: em novembro e dezembro, 1/11 do ano corrente; de janeiro a outubro, 1/11 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08 e de 1/10 para 1/11 em 2026-11-11 (base limpa, coleta do zero).
  // Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo" e o CICLO_MES de js/formato.js.
  cicloInicio: { mes: 11, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
// acao.idUnidade é obrigatório: o mesmo IdPaciente pode existir em duas unidades.
const sqlRegistrarAcao = (acao) => {
  const unidade = sqlN(acao.idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlRegistrarAcao: idUnidade não informado.');
  }
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${unidade} AS IdUnidade, ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdUnidade = origem.IdUnidade AND destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdUnidade, IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdUnidade, IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra } da unidade. Blocos de 500 (VALUES aceita até 1000 linhas).
// Os ids das listas do CNN são de cada clínica: a chave é (IdUnidade, Tipo, Id).
const sqlCadastros = (linhas, idUnidade) => {
  const unidade = sqlN(idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlCadastros: idUnidade não informado.');
  }
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.IdUnidade = ${unidade} AND destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (IdUnidade, Tipo, Id, Nome, Extra) VALUES (${unidade}, origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// Nó "montar info bloqueio" (bloqueio às 01:00). Um item por paciente com falta no período analisado
// (início do ciclo até hoje) e com o prazo 60/90/180 da falta vigente ainda correndo:
//   - prazo já cumprido (falta lançada atrasada, por exemplo) -> não bloqueia (a liberação automática não teria o que fazer);
//   - ativo no CNN (ou sem resposta do GET) -> bloquear (PATCH);
//   - já inativo no CNN e sem bloqueio registrado para esta falta -> só registrar (sem PATCH);
//   - já inativo e já registrado -> nada a fazer.
// Quem foi liberado ou isento no painel por esta mesma falta nem chega aqui (filtro em "ids da consulta").
// Sem ninguém: um item { nadaABloquear: true } com o resumo do porquê.
const ativoPorPaciente = new Map();

try {
  for (const item of $('GET paciente por id').all()) {
    const paciente = item.json ?? {};
    const id = Number(paciente.id);

    if (!Number.isFinite(id) || paciente.error || paciente.message) {
      continue;
    }

    if (typeof paciente.ativo === 'boolean') {
      ativoPorPaciente.set(id, paciente.ativo);
    }
  }
} catch (erro) {
  // GET paciente nao rodou neste ramo
}

const hoje = hojeSp();
const linhas = linhasSql(items);
const resumo = { analisados: linhas.length, jaRegistrado: 0, prazoCumprido: 0, invalidos: 0 };

const saida = linhas.flatMap((linha) => {
  const numeroFalta = Number(linha.NumeroFalta ?? linha.numeroFalta ?? 0);
  const idPaciente = Number(linha.IdPaciente ?? linha.idPaciente);

  if (!Number.isFinite(idPaciente) || numeroFalta < 1) {
    resumo.invalidos += 1;
    return [];
  }

  // O prazo vai para o controle como "liberável a partir de". Prazo já cumprido: não bloqueia.
  const diasBloqueio = diasPorFalta(numeroFalta);
  const nomePaciente = linha.NomePaciente ?? linha.nomePaciente ?? null;
  const dataInicio = dataIso(linha.DataFalta ?? linha.dataFalta);
  const dataFim = somarDias(dataInicio, diasBloqueio);

  if (dataFim && dataFim < hoje) {
    resumo.prazoCumprido += 1;
    return [];
  }

  const idAgenda = linha.IdAgenda ?? linha.idAgenda ?? null;
  const bloqueioRegistrado =
    linha.SituacaoControle === 'BLOQUEADO' && String(linha.IdAgendaReferencia ?? '') === String(idAgenda ?? '');

  const jaInativo = ativoPorPaciente.get(idPaciente) === false;
  if (jaInativo && bloqueioRegistrado) {
    resumo.jaRegistrado += 1;
    return [];
  }

  return [{
    json: {
      acao: 'BLOQUEAR',
      apenasRegistrar: jaInativo,
      ativo: false,
      ativoAntes: ativoPorPaciente.has(idPaciente) ? ativoPorPaciente.get(idPaciente) : null,
      idPaciente,
      nomePaciente,
      numeroFalta,
      nivelBloqueio: Math.min(numeroFalta, maiorFaltaRegra),
      diasBloqueio,
      dataInicioBloqueio: dataInicio,
      dataFimBloqueio: dataFim,
      idAgenda,
      mensagem: jaInativo
        ? `Registrar bloqueio de ${nomePaciente ?? idPaciente} (já inativo no CNN, falta ${numeroFalta}); liberável a partir de ${dataFim}.`
        : `Bloquear paciente ${nomePaciente ?? idPaciente} (falta ${numeroFalta}); liberável a partir de ${dataFim}.`
    }
  }];
});

// Ninguém para bloquear: devolve um item de resumo em vez de lista vazia, para a execução
// mostrar o motivo e seguir até o fim (o IF "há o que bloquear?" desvia para "nada a bloquear").
if (!saida.length) {
  return [{
    json: {
      nadaABloquear: true,
      hoje,
      ...resumo,
      mensagem: `Nada a bloquear hoje (${hoje}): ${resumo.analisados} paciente(s) com falta no período; `
        + `${resumo.jaRegistrado} já inativo(s) no CNN e registrado(s); `
        + `${resumo.prazoCumprido} com o prazo já cumprido (não bloqueia).`
    }
  }];
}

return saida;

parameters.content:
## 2. Gravar no SQL

Uma query, uma transacao:
- MERGE dos cadastros (CtlCnnCadastro);
- falta nova: INSERT; ja gravada: UPDATE
  (tipo de consulta, rotulo, profissional...);
- procedimentos (CtlCnnFaltaProcedimento);
- NumeroFalta reordenado por DataFalta.

Profissional: agenda.idPessoaExecutor =
idpessoa da lista de executores.

parameters.jsCode:
// ===== Regra do bloqueio por falta (fonte única: workflows/code/_regra.js) =====
// O inject.mjs copia este bloco para o início de todo nó Code que usa prazo ou ciclo.
// Para mudar a regra: edite aqui, rode `npm run inject` e publique os workflows no n8n.
const REGRA = {
  // Prazo (dias) a partir da falta vigente do ciclo. A maior chave vale para "essa ou mais".
  // Toda falta do período (ciclo) bloqueia quem está ativo no CNN enquanto o prazo corre; quem já cumpriu
  // o prazo não é bloqueado. Antes do fim do prazo, liberar só com solicitação aprovada pelo admin;
  // depois, a liberação automática (02:00) libera.
  prazosDias: { 1: 60, 2: 90, 3: 180 },
  // Início do ciclo: em novembro e dezembro, 1/11 do ano corrente; de janeiro a outubro, 1/11 do ano anterior.
  // Mudou de 1/8 para 1/10 em 2026-10-08 e de 1/10 para 1/11 em 2026-11-11 (base limpa, coleta do zero).
  // Mudar aqui exige mudar também a URL do nó "GET agenda do ciclo" e o CICLO_MES de js/formato.js.
  cicloInicio: { mes: 11, dia: 1 },
  fuso: 'America/Sao_Paulo',
  // Só informativos (os crons ficam nos nós "Todo dia 01:00" e "Todo dia 02:00" dos workflows).
  horarioBloqueio: '01:00',
  liberacaoAutomatica: true,
  horarioLiberacao: '02:00',
};

const pad2 = (valor) => String(valor).padStart(2, '0');
const agoraSp = () => $now.setZone(REGRA.fuso);
const hojeSp = () => agoraSp().toFormat('yyyy-MM-dd');

const inicioCiclo = () => {
  const agora = agoraSp();
  const { mes, dia } = REGRA.cicloInicio;
  const jaComecou = agora.month > mes || (agora.month === mes && agora.day >= dia);
  const ano = jaComecou ? agora.year : agora.year - 1;
  return `${ano}-${pad2(mes)}-${pad2(dia)}`;
};

const maiorFaltaRegra = Math.max(...Object.keys(REGRA.prazosDias).map(Number));

const diasPorFalta = (numeroFalta) => {
  const numero = Math.min(Math.max(Number(numeroFalta) || 1, 1), maiorFaltaRegra);
  return REGRA.prazosDias[numero];
};

// Mesmo cálculo em SQL: CASE WHEN col >= 3 THEN 180 WHEN col = 2 THEN 90 ELSE 60 END.
const sqlDiasCase = (coluna) => {
  const chaves = Object.keys(REGRA.prazosDias).map(Number).sort((a, b) => b - a);
  const partes = chaves
    .filter((chave) => chave !== 1)
    .map((chave) => `WHEN ${coluna} ${chave === maiorFaltaRegra ? '>=' : '='} ${chave} THEN ${REGRA.prazosDias[chave]}`);
  return `CASE ${partes.join(' ')} ELSE ${REGRA.prazosDias[1]} END`;
};

const dataIso = (valor) => {
  if (!valor) {
    return null;
  }

  if (valor instanceof Date) {
    return Number.isNaN(valor.getTime()) ? null : valor.toISOString().slice(0, 10);
  }

  const texto = String(valor).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(texto) ? texto : null;
};

const somarDias = (valor, dias) => {
  const inicio = dataIso(valor);
  if (!inicio || !dias) {
    return null;
  }

  const [ano, mes, dia] = inicio.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  if (Number.isNaN(data.getTime())) {
    return null;
  }

  data.setUTCDate(data.getUTCDate() + dias);
  return data.toISOString().slice(0, 10);
};
// ===== fim da regra =====

// ===== Helpers de SQL (fonte única: workflows/code/_sql.js) =====
// O SQL é montado por texto: todo valor passa por uma destas funções.
const sqlN = (valor) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const numero = Number(valor);
  return Number.isFinite(numero) ? String(Math.trunc(numero)) : 'NULL';
};

const sqlS = (valor, maxLength) => {
  if (valor === null || valor === undefined || valor === '') {
    return 'NULL';
  }

  const texto = String(valor).slice(0, maxLength ?? 4000).replace(/'/g, "''");
  return `N'${texto}'`;
};

const sqlDate = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  const data = String(valor).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) {
    return 'NULL';
  }

  return `CONVERT(date, '${data}', 23)`;
};

const sqlTime = (valor) => {
  if (!valor) {
    return 'NULL';
  }

  let hora = String(valor).trim();
  if (/^\d{2}:\d{2}$/.test(hora)) {
    hora = `${hora}:00`;
  }

  if (!/^\d{2}:\d{2}:\d{2}$/.test(hora)) {
    return 'NULL';
  }

  return `CONVERT(time(0), '${hora}')`;
};

const sqlBit = (valor) => {
  if (valor === null || valor === undefined) {
    return 'NULL';
  }

  return valor ? '1' : '0';
};

// Linhas devolvidas por um nó Microsoft SQL, em qualquer dos formatos que o n8n já usou.
const linhasSql = (itens) => {
  const linhas = [];

  for (const item of itens) {
    const payload = item?.json ?? {};

    if (Array.isArray(payload.recordset)) {
      linhas.push(...payload.recordset);
    } else if (Array.isArray(payload.recordsets?.[0])) {
      linhas.push(...payload.recordsets[0]);
    } else if (Object.keys(payload).length > 0 && payload.error === undefined) {
      linhas.push(payload);
    }
  }

  return linhas;
};

const erroSql = (itens) => {
  const comErro = itens.find((item) => item?.json?.error !== undefined);
  if (!comErro) {
    return null;
  }

  const erro = comErro.json.error;
  return typeof erro === 'string' ? erro : erro?.message || 'Falha no SQL Server.';
};

// Resposta de um nó HTTP com "Full Response" e "Never Error": { statusCode, body }.
// Com erro de rede e onError = continueRegularOutput, chega { error: {...} }.
const lerRespostaHttp = (json) => {
  const resposta = json ?? {};
  const erro = resposta.error;
  const statusCode = Number(resposta.statusCode ?? erro?.httpCode ?? erro?.status ?? erro?.cause?.status) || null;
  const body = resposta.body !== undefined ? resposta.body : erro ? null : resposta;
  const ok = !erro && statusCode !== null && statusCode >= 200 && statusCode < 300;
  const texto = typeof body === 'string' ? body : body ? JSON.stringify(body) : erro?.message || String(erro ?? '');
  return { ok, statusCode, body, erro: erro ? erro.message || String(erro) : null, texto: texto.slice(0, 1000) };
};

// Grava uma ação na auditoria e, se deu certo, atualiza a tabela de controle. Devolve o SQL completo.
// acao.idUnidade é obrigatório: o mesmo IdPaciente pode existir em duas unidades.
const sqlRegistrarAcao = (acao) => {
  const unidade = sqlN(acao.idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlRegistrarAcao: idUnidade não informado.');
  }
  const situacao = acao.acao === 'LIBERACAO' ? 'LIBERADO' : 'BLOQUEADO';
  const merge = acao.sucesso
    ? `
MERGE dbo.CtlCnnControlePaciente WITH (HOLDLOCK) AS destino
USING (SELECT ${unidade} AS IdUnidade, ${sqlN(acao.idPaciente)} AS IdPaciente) AS origem
    ON destino.IdUnidade = origem.IdUnidade AND destino.IdPaciente = origem.IdPaciente
WHEN MATCHED THEN
    UPDATE SET
        NomePaciente = COALESCE(${sqlS(acao.nomePaciente, 200)}, destino.NomePaciente),
        Situacao = ${sqlS(situacao, 20)},
        IdAgendaReferencia = ${sqlN(acao.idAgenda)},
        NumeroFalta = ${sqlN(acao.numeroFalta)},
        DataInicioBloqueio = ${sqlDate(acao.dataInicioBloqueio)},
        DataFimBloqueio = ${sqlDate(acao.dataFimBloqueio)},
        UltimaAcao = ${sqlS(acao.acao, 20)},
        OrigemUltimaAcao = ${sqlS(acao.origem, 20)},
        UltimaAcaoPor = ${sqlS(acao.usuario, 100)},
        MotivoUltimaAcao = ${sqlS(acao.motivo, 500)},
        IdUltimaAcao = @IdAcao,
        UltimaAcaoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (
        IdUnidade, IdPaciente, NomePaciente, Situacao, IdAgendaReferencia, NumeroFalta,
        DataInicioBloqueio, DataFimBloqueio, UltimaAcao, OrigemUltimaAcao,
        UltimaAcaoPor, MotivoUltimaAcao, IdUltimaAcao
    )
    VALUES (
        ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(situacao, 20)}, ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)},
        ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)},
        ${sqlS(acao.usuario, 100)}, ${sqlS(acao.motivo, 500)}, @IdAcao
    );`
    : '';

  // Solicitações de desbloqueio (dbo.CtlCnnSolicitacao), na mesma transação da auditoria.
  const idSolicitacao = sqlN(acao.idSolicitacao);
  const temSolicitacao = idSolicitacao !== 'NULL';
  const liberou = acao.sucesso && acao.acao === 'LIBERACAO';
  const solicitacoes = [];

  if (temSolicitacao && liberou) {
    // A solicitação usada nesta liberação fica LIBERADA (com "Aprovar e liberar", a decisão vai junto).
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'LIBERADA',
    LiberadoPor = ${sqlS(acao.usuario, 100)},
    LiberadoEm = SYSUTCDATETIME(),
    IdAcao = @IdAcao,
    DecididoPor = COALESCE(DecididoPor, ${sqlS(acao.aprovador, 100)}),
    DecididoEm = COALESCE(DecididoEm, CASE WHEN ${sqlS(acao.aprovador, 100)} IS NULL THEN NULL ELSE SYSUTCDATETIME() END),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status IN (N'PENDENTE', N'APROVADA');`);
  } else if (temSolicitacao && acao.aprovador) {
    // "Aprovar e liberar" com o CNN fora do ar: a aprovação vale; a liberação pode ser tentada de novo.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'APROVADA',
    DecididoPor = ${sqlS(acao.aprovador, 100)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE Id = ${idSolicitacao}
  AND IdUnidade = ${unidade}
  AND Status = N'PENDENTE';`);
  }

  if (liberou) {
    // Liberado por outro caminho (prazo cumprido): as outras solicitações abertas perdem o sentido.
    const motivoEncerramento = acao.origem === 'AUTOMATICO'
      ? 'Prazo cumprido: paciente liberado pela rotina automática.'
      : `Paciente liberado por ${acao.usuario || 'outro usuário'}.`;
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = ${sqlS(motivoEncerramento, 500)},
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')${temSolicitacao ? `\n  AND Id <> ${idSolicitacao}` : ''};`);
  }

  if (acao.sucesso && acao.acao === 'BLOQUEIO') {
    // Bloqueio por uma falta nova: a solicitação feita para a falta anterior não vale mais.
    solicitacoes.push(`
UPDATE dbo.CtlCnnSolicitacao
SET Status = N'ENCERRADA',
    MotivoDecisao = N'Nova falta registrada: a solicitação era da falta anterior.',
    DecididoEm = SYSUTCDATETIME(),
    AtualizadoEm = SYSUTCDATETIME()
WHERE IdUnidade = ${unidade}
  AND IdPaciente = ${sqlN(acao.idPaciente)}
  AND Status IN (N'PENDENTE', N'APROVADA')
  AND IdAgendaReferencia <> ${sqlN(acao.idAgenda)};`);
  }

  return `USE INTEGRACAO;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

INSERT INTO dbo.CtlCnnAcaoPaciente (
    IdUnidade, IdPaciente, NomePaciente, Acao, Origem, Usuario, Motivo,
    IdAgendaReferencia, NumeroFalta, DataInicioBloqueio, DataFimBloqueio,
    Antecipada, AtivoAntes, Sucesso, HttpStatus, RespostaApi, IdExecucaoN8n, IdSolicitacao
)
VALUES (
    ${unidade}, ${sqlN(acao.idPaciente)}, ${sqlS(acao.nomePaciente, 200)}, ${sqlS(acao.acao, 20)}, ${sqlS(acao.origem, 20)}, ${sqlS(acao.usuario || 'desconhecido', 100)}, ${sqlS(acao.motivo, 500)},
    ${sqlN(acao.idAgenda)}, ${sqlN(acao.numeroFalta)}, ${sqlDate(acao.dataInicioBloqueio)}, ${sqlDate(acao.dataFimBloqueio)},
    ${sqlBit(Boolean(acao.antecipada))}, ${sqlBit(acao.ativoAntes)}, ${sqlBit(Boolean(acao.sucesso))}, ${sqlN(acao.httpStatus)}, ${sqlS(acao.respostaApi, 1000)}, ${sqlS(acao.idExecucao, 50)}, ${idSolicitacao}
);

DECLARE @IdAcao BIGINT = CONVERT(BIGINT, SCOPE_IDENTITY());
${merge}
${solicitacoes.join('\n')}

COMMIT TRANSACTION;

SELECT @IdAcao AS IdAcao, CAST(${sqlBit(Boolean(acao.sucesso))} AS bit) AS Sucesso;`;
};
// Junta os itens de um nó HTTP paginado da API do CNN: cada página chega como { lista: [...] }.
// Página com erro (onError = continueRegularOutput) é ignorada.
const listaDaApi = (itens) => {
  const lista = [];

  for (const item of itens || []) {
    const pagina = item?.json ?? {};
    if (Array.isArray(pagina.lista)) {
      lista.push(...pagina.lista);
    }
  }

  return lista;
};

// Itens de um nó que pode não existir (ou não ter rodado) neste workflow: lista vazia em vez de erro.
const itensDoNo = (nome) => {
  try {
    return $(nome).all();
  } catch (erro) {
    return [];
  }
};

// MERGE em dbo.CtlCnnCadastro: linhas { tipo, id, nome, extra } da unidade. Blocos de 500 (VALUES aceita até 1000 linhas).
// Os ids das listas do CNN são de cada clínica: a chave é (IdUnidade, Tipo, Id).
const sqlCadastros = (linhas, idUnidade) => {
  const unidade = sqlN(idUnidade);
  if (unidade === 'NULL') {
    throw new Error('sqlCadastros: idUnidade não informado.');
  }
  const validas = [];
  const vistos = new Set();

  for (const linha of linhas) {
    const id = Number(linha.id);
    const chave = `${linha.tipo}:${id}`;
    if (!linha.tipo || !Number.isFinite(id) || vistos.has(chave)) {
      continue;
    }
    vistos.add(chave);
    validas.push(`(${sqlS(linha.tipo, 20)}, ${sqlN(id)}, ${sqlS(linha.nome, 200)}, ${sqlS(linha.extra, 100)})`);
  }

  const blocos = [];
  for (let i = 0; i < validas.length; i += 500) {
    blocos.push(`
MERGE dbo.CtlCnnCadastro WITH (HOLDLOCK) AS destino
USING (VALUES
    ${validas.slice(i, i + 500).join(',\n    ')}
) AS origem (Tipo, Id, Nome, Extra)
    ON destino.IdUnidade = ${unidade} AND destino.Tipo = origem.Tipo AND destino.Id = origem.Id
WHEN MATCHED AND (ISNULL(destino.Nome, N'') <> ISNULL(origem.Nome, N'') OR ISNULL(destino.Extra, N'') <> ISNULL(origem.Extra, N'')) THEN
    UPDATE SET Nome = origem.Nome, Extra = origem.Extra, AtualizadoEm = SYSUTCDATETIME()
WHEN NOT MATCHED THEN
    INSERT (IdUnidade, Tipo, Id, Nome, Extra) VALUES (${unidade}, origem.Tipo, origem.Id, origem.Nome, origem.Extra);`);
  }

  return blocos.join('\n');
};
// ===== fim dos helpers de SQL =====

// ===== Unidade da execução (fonte única: workflows/code/_unidade.js) =====
// Cada unidade (clínica do CNN) tem um IdUnidade (chave em todas as tabelas) e um código (dbo.CtlCnnUnidade).
// O CID do CNN de cada unidade fica na variável do n8n CNN_CID_<código> (ex.: CNN_CID_ZARNS_SALVADOR), na tela
// Variables ($vars) ou no ambiente do servidor ($env), nunca no fluxo: os headers "clinicaNasNuvens-cid" leem por ela.
const CODIGO_UNIDADE = /^[A-Z0-9_]{1,40}$/;

// { idUnidade, codigoUnidade } de quem chamou (a Vercel no webhook, ou o fluxo principal no subfluxo do bloqueio).
const lerUnidade = (origem) => {
  const idUnidade = Number(origem?.idUnidade);
  const codigoUnidade = String(origem?.codigoUnidade ?? '').trim();
  if (!Number.isSafeInteger(idUnidade) || idUnidade <= 0 || idUnidade > 32767 || !CODIGO_UNIDADE.test(codigoUnidade)) {
    return null;
  }
  return { idUnidade, codigoUnidade };
};

// Unidade desta execução: nó "Unidade" (subfluxo do bloqueio) ou "Validar" (workflow Ações).
const unidadeAtual = () => {
  for (const nome of ['Unidade', 'Validar']) {
    try {
      const unidade = lerUnidade($(nome).first().json);
      if (unidade) {
        return unidade;
      }
    } catch (erro) {
      // o nó não existe (ou não rodou) neste workflow
    }
  }
  throw new Error('Unidade não informada nesta execução (idUnidade e codigoUnidade).');
};

// CID da unidade: Variables do n8n ($vars, tela Variables) e, se não tiver, variável de ambiente do servidor ($env).
// Vazio: a chamada ao CNN não pode seguir.
const cidDaUnidade = (codigoUnidade) => {
  const nome = `CNN_CID_${codigoUnidade}`;
  for (const ler of [() => $vars[nome], () => $env[nome]]) {
    try {
      const valor = String(ler() ?? '').trim();
      if (valor) {
        return valor;
      }
    } catch (erro) {
      // $vars indisponível, ou N8N_BLOCK_ENV_ACCESS_IN_NODE=true bloqueando o $env
    }
  }
  return '';
};

const semCidMensagem = (codigoUnidade) =>
  `CID da unidade ${codigoUnidade} não configurado no n8n (variável CNN_CID_${codigoUnidade} em Variables).`;
// ===== fim da unidade =====

// Nó "montar registro" (bloqueio às 01:00). Roda para cada paciente do laço, depois do PATCH
// (ou no lugar dele, quando o paciente já estava inativo no CNN e só falta registrar):
// grava o resultado na auditoria (Origem AUTOMATICO) e, se deu certo, marca BLOQUEADO na tabela de controle.
let alvo = {};
try {
  alvo = $('loop bloqueios').itemMatching(0).json;
} catch (erro) {
  alvo = $('loop bloqueios').first().json;
}

const SO_REGISTRO = 'Sem PATCH: paciente já estava inativo no CNN; bloqueio só registrado pela automação.';
const resposta = alvo.apenasRegistrar
  ? { ok: true, statusCode: null, erro: null, texto: SO_REGISTRO }
  : lerRespostaHttp($input.first().json);

const query = sqlRegistrarAcao({
  idUnidade: unidadeAtual().idUnidade,
  idPaciente: alvo.idPaciente,
  nomePaciente: alvo.nomePaciente,
  acao: 'BLOQUEIO',
  origem: 'AUTOMATICO',
  usuario: 'n8n',
  motivo: `Falta ${alvo.numeroFalta} no ciclo: bloqueio de ${alvo.diasBloqueio} dias.`,
  idAgenda: alvo.idAgenda,
  numeroFalta: alvo.numeroFalta,
  dataInicioBloqueio: alvo.dataInicioBloqueio,
  dataFimBloqueio: alvo.dataFimBloqueio,
  antecipada: false,
  ativoAntes: typeof alvo.ativoAntes === 'boolean' ? alvo.ativoAntes : null,
  sucesso: resposta.ok,
  httpStatus: resposta.statusCode,
  respostaApi: alvo.apenasRegistrar ? SO_REGISTRO : resposta.ok ? null : resposta.erro || resposta.texto,
  idExecucao: $execution.id,
});

return [{
  json: {
    query,
    idPaciente: alvo.idPaciente,
    apenasRegistrar: Boolean(alvo.apenasRegistrar),
    sucesso: resposta.ok,
    httpStatus: resposta.statusCode
  }
}];

// Nó "pacientes únicos" (bloqueio às 01:00 e botão Bloquear do painel).
// Um item por paciente: "GET paciente por id" roda uma vez por paciente, e não uma vez por falta.
// O GET traz nome, CPF e contato (gravados com a falta) e o "ativo" usado em "montar info bloqueio".
const vistos = new Set();
const saida = [];

for (const item of $input.all()) {
  const idPaciente = Number(item.json?.idPaciente);
  if (!Number.isFinite(idPaciente) || vistos.has(idPaciente)) {
    continue;
  }
  vistos.add(idPaciente);
  saida.push({ json: { idPaciente } });
}

return saida;

// ===== Unidade da execução (fonte única: workflows/code/_unidade.js) =====
// Cada unidade (clínica do CNN) tem um IdUnidade (chave em todas as tabelas) e um código (dbo.CtlCnnUnidade).
// O CID do CNN de cada unidade fica na variável do n8n CNN_CID_<código> (ex.: CNN_CID_ZARNS_SALVADOR), na tela
// Variables ($vars) ou no ambiente do servidor ($env), nunca no fluxo: os headers "clinicaNasNuvens-cid" leem por ela.
const CODIGO_UNIDADE = /^[A-Z0-9_]{1,40}$/;

// { idUnidade, codigoUnidade } de quem chamou (a Vercel no webhook, ou o fluxo principal no subfluxo do bloqueio).
const lerUnidade = (origem) => {
  const idUnidade = Number(origem?.idUnidade);
  const codigoUnidade = String(origem?.codigoUnidade ?? '').trim();
  if (!Number.isSafeInteger(idUnidade) || idUnidade <= 0 || idUnidade > 32767 || !CODIGO_UNIDADE.test(codigoUnidade)) {
    return null;
  }
  return { idUnidade, codigoUnidade };
};

// Unidade desta execução: nó "Unidade" (subfluxo do bloqueio) ou "Validar" (workflow Ações).
const unidadeAtual = () => {
  for (const nome of ['Unidade', 'Validar']) {
    try {
      const unidade = lerUnidade($(nome).first().json);
      if (unidade) {
        return unidade;
      }
    } catch (erro) {
      // o nó não existe (ou não rodou) neste workflow
    }
  }
  throw new Error('Unidade não informada nesta execução (idUnidade e codigoUnidade).');
};

// CID da unidade: Variables do n8n ($vars, tela Variables) e, se não tiver, variável de ambiente do servidor ($env).
// Vazio: a chamada ao CNN não pode seguir.
const cidDaUnidade = (codigoUnidade) => {
  const nome = `CNN_CID_${codigoUnidade}`;
  for (const ler of [() => $vars[nome], () => $env[nome]]) {
    try {
      const valor = String(ler() ?? '').trim();
      if (valor) {
        return valor;
      }
    } catch (erro) {
      // $vars indisponível, ou N8N_BLOCK_ENV_ACCESS_IN_NODE=true bloqueando o $env
    }
  }
  return '';
};

const semCidMensagem = (codigoUnidade) =>
  `CID da unidade ${codigoUnidade} não configurado no n8n (variável CNN_CID_${codigoUnidade} em Variables).`;
// ===== fim da unidade =====

// Nó "conferir unidade" (subfluxo "Bloqueio por unidade"). Recebe { idUnidade, codigoUnidade } do fluxo principal
// (nó "Unidade") e para logo se a unidade for inválida ou se o CID dela não estiver configurado no n8n:
// sem CID, todas as chamadas ao CNN seriam recusadas.
const unidade = lerUnidade($('Unidade').first().json);

if (!unidade) {
  throw new Error('Unidade inválida: o subfluxo precisa de idUnidade e codigoUnidade (chamado pelo fluxo principal do bloqueio).');
}

if (!cidDaUnidade(unidade.codigoUnidade)) {
  throw new Error(semCidMensagem(unidade.codigoUnidade));
}

return [{ json: { ...unidade, nomeUnidade: $('Unidade').first().json.nomeUnidade || unidade.codigoUnidade } }];
